        public static IEnumerable<TestCaseData> NativeCases()
        {
            for (int index = 0; index < NativeVectors.Length; index++)
                yield return new TestCaseData(NativeVectors[index]).SetName("OriginalAiNative_" + index.ToString(CultureInfo.InvariantCulture));
        }

        private static int Number(string value) => int.Parse(value, CultureInfo.InvariantCulture);

        private static int[] Numbers(string value) => value.Length == 0 ? Array.Empty<int>() : value.Split(',').Select(Number).ToArray();

        private static string Join(IEnumerable<int> values) => string.Join(",", values);

        private static (BattleAi Ai, Port Port, BattleRandom Random) Create(string variant, int seed = 1)
        {
            var random = new BattleRandom(seed, variant);
            var port = new Port();
            var ai = new BattleAi(variant == "PAL3A", random, port);
            port.Ai = ai;
            return (ai, port, random);
        }

        private static void SetRoles(BattleAi ai, int[] valid, int[] hp = null)
        {
            for (int index = 0; index < valid.Length; index++)
            {
                int value = hp == null ? 100 : hp[index];
                ai.Roles[valid[index]] = new BattleAiRole { Valid = true, Alive = value > 0, Hp = value, MaxHp = 100 };
            }
        }

        [TestCaseSource(nameof(NativeCases))]
        public void MatchesReleasedExecutable(string encoded)
        {
            string[] data = encoded.Split('|');
            string variant = data[1];
            if (data[0] == "H")
            {
                Assert.That(BattleAi.HpState(Number(data[2]), Number(data[3])), Is.EqualTo(Number(data[4])));
                return;
            }
            if (data[0] == "E")
            {
                var (ai, port, random) = Create(variant, Number(data[3]));
                SetRoles(ai, Numbers(data[4]));
                foreach (string pair in data[5].Split(new[] { ',' }, StringSplitOptions.RemoveEmptyEntries))
                {
                    int[] parts = pair.Split(':').Select(Number).ToArray();
                    int offset = parts[0];
                    if (offset < 0xd10)
                    {
                        int value = offset - 0x630;
                        ai.Demand[value / 160, value % 160 / 16].Satisfy = parts[1];
                    }
                    else if (offset < 0xdb0)
                        ai.EnemyDemand[(offset - 0xd10) / 16].Satisfy = parts[1];
                    else
                        ai.FriendDemand[(offset - 0xdb0) / 16].Satisfy = parts[1];
                }
                int source = Number(data[6]);
                ai.Roles[source].Chaos = data[7] == "18";
                ai.Roles[source].Madness = data[7] == "19";
                foreach (int fled in Numbers(data[8]))
                    ai.Roles[fled].Fled = true;
                ai.Roles[source].Boss = data[9] == "1";
                if (data[10].Length > 0)
                {
                    ai.FriendDemand[5].Satisfy = 40;
                    port.Scene = Number(data[11]);
                    ai.Roles[source].Skills = Numbers(data[10]).Select((id, index) =>
                    {
                        var operations = new int[32];
                        if (index < 3)
                            operations[index == 0 ? 6 : index == 1 ? 5 : 0] = 1;
                        return new BattleAiSkill { Id = id, Type = 1, Range = 3, StateOperations = operations };
                    }).ToArray();
                }
                ai.Roles[source].Identity = Number(data[12]);
                port.Success = data[13];
                bool actual = data[2] switch
                {
                    "well" => ai.HandleEnemyState(source, 0),
                    "weak" => ai.HandleEnemyState(source, 1),
                    "low" or "low-7325" => ai.HandleEnemyState(source, 2),
                    "chaos" => ai.HandleEnemyChaos(source),
                    "negative" => ai.HandleFriendNegative(source),
                    "affirmative" => ai.HandleFriendAffirmative(source),
                    _ => throw new ArgumentException(data[2])
                };
                Assert.That(actual, Is.EqualTo(data[14] == "1"));
                Assert.That(string.Join(";", port.Attempts), Is.EqualTo(data[15]));
                Assert.That(random.State.ToString(CultureInfo.InvariantCulture), Is.EqualTo(data[16]));
                return;
            }
            if (data[0] == "D")
            {
                var (ai, _, _) = Create(variant);
                SetRoles(ai, Numbers(data[2]), Numbers(data[3]));
                ai.CheckDemands();
                foreach (string row in data[4].Split(';'))
                {
                    string[] parts = row.Split(':');
                    int role = Number(parts[0]);
                    Assert.That(Enumerable.Range(0, 10).Select(kind => ai.Demand[role, kind].Satisfy), Is.EqualTo(Numbers(parts[1])));
                }
                Assert.That(ai.EnemyDemand.Select(demand => demand.Satisfy), Is.EqualTo(Numbers(data[5])));
                Assert.That(ai.FriendDemand.Select(demand => demand.Satisfy), Is.EqualTo(Numbers(data[6])));
                return;
            }
            if (data[0] == "B")
            {
                var (ai, port, _) = Create(variant);
                ai.Roles[5].Identity = Number(data[2]);
                ai.Roles[5].Mp = Number(data[3]);
                ai.Roles[5].MaxMp = Number(data[4]);
                port.Success = "SpecAI";
                Assert.That(ai.HandleSpecialBoss(5), Is.EqualTo(data[5] == "1"));
                Assert.That(port.LastAbility, Is.EqualTo(data[5] == "1" ? 7709 : 0));
                return;
            }
            if (data[0] == "F")
            {
                var (ai, port, random) = Create(variant);
                SetRoles(ai, new[] { 0, 5, 6 }, new[] { 100 }.Concat(Numbers(data[2])).ToArray());
                int[] maxima = Numbers(data[3]);
                ai.Roles[5].MaxHp = maxima[0];
                ai.Roles[6].MaxHp = maxima[1];
                foreach (int fled in Numbers(data[4]))
                    ai.Roles[fled].Fled = true;
                port.Success = "Normal";
                Assert.That(ai.PlayerNormal(0, false), Is.EqualTo(data[5] == "1"));
                Assert.That(string.Join(";", port.Attempts), Is.EqualTo(data[6]));
                Assert.That(random.State.ToString(CultureInfo.InvariantCulture), Is.EqualTo(data[7]));
                return;
            }
            if (data[0] == "A")
            {
                var (ai, _, _) = Create(variant);
                foreach (BattleAiRole role in ai.Roles)
                    role.Profile = new BattleAiProfile { Attack = true, Skill = true, Negative = data[4] == "1" };
                ai.SetAutomatic(data[3] == "1", data[2] == "1");
                Assert.That(ai.Automatic, Is.EqualTo(data[6] == "1"));
                Assert.That(string.Join(";", ai.Roles.Select(role => Join(new[] { role.Profile.Attack, role.Profile.Magic, role.Profile.Skill, role.Profile.Item, role.Profile.Negative, role.Profile.Enabled }.Select(value => value ? 1 : 0)))), Is.EqualTo(data[5]));
                return;
            }
            if (data[0] == "S")
            {
                var (ai, port, _) = Create(variant);
                SetRoles(ai, new[] { 5 });
                ai.Roles[5].Skills = data[5].Split(';').Select(row =>
                {
                    int[] fields = Numbers(row);
                    return new BattleAiSkill { Id = fields[0], Type = fields[1], Range = fields[2], Power = fields[3] };
                }).ToArray();
                port.Denied = new HashSet<int>(Numbers(data[6]));
                Assert.That(ai.SelectMagic(5, data[2] == "attack", data[3] == "1", Number(data[4])), Is.EqualTo(Number(data[7])));
                Assert.That(string.Join(",", port.Eligibility), Is.EqualTo(data[8]));
                return;
            }
            if (data[0] == "T")
            {
                var (ai, _, _) = Create(variant);
                int[] levels = Numbers(data[2]);
                ai.Roles[5].Skills = Enumerable.Range(0, 4).Select(index => new BattleAiSkill { Id = 9001 + index, Level = index < 3 ? levels[index] : 1 }).ToArray();
                Assert.That(ai.MonsterSkillLevel(5, Number(data[3])), Is.EqualTo(Number(data[4])));
                return;
            }
            if (data[0] == "Q")
            {
                var (ai, port, random) = Create(variant, Number(data[4]));
                SetRoles(ai, new[] { 5 });
                int[] operations = Numbers(data[3]);
                int state = data[2] == "debuff" ? 6 : data[2] == "buff" ? 5 : 0;
                ai.Roles[5].Skills = Enumerable.Range(0, 4).Select(index =>
                {
                    var values = new int[32];
                    values[state] = operations[index];
                    return new BattleAiSkill { Id = 9001 + index, StateOperations = values };
                }).ToArray();
                Assert.That(ai.QueryStatusMagic(5, (BattleAiStatusQuery)Enum.Parse(typeof(BattleAiStatusQuery), data[2], true)), Is.EqualTo(Number(data[5])));
                Assert.That(random.State.ToString(CultureInfo.InvariantCulture), Is.EqualTo(data[6]));
                Assert.That(string.Join(",", port.Eligibility), Is.EqualTo(data[7]));
                return;
            }
            if (data[0] == "R")
            {
                var (ai, port, _) = Create(variant);
                SetRoles(ai, new[] { 0, 5 });
                port.RepeatCan = data[3] == "1";
                port.RepeatDead = data[4] == "1";
                ai.NewRole[0] = data[5] == "1";
                port.RepeatAttack = data[6] == "1";
                port.RepeatTarget = Number(data[7]);
                int kind = Number(data[2]);
                port.Fallback = !port.RepeatCan && kind is 0x104 or 0x105 or 0x106 or 0x10f || variant == "PAL3" && kind == 0x10f;
                var command = new BattleAiCommand { Kind = kind, AbilityId = 301, Source = 0, Target = 8, TargetMask = Enumerable.Repeat(true, 11).ToArray() };
                Assert.That(ai.Repeat(0, command), Is.EqualTo(data[8] == "1"));
                Assert.That(unchecked((uint)command.Target).ToString(CultureInfo.InvariantCulture), Is.EqualTo(data[9]));
                Assert.That(Join(command.TargetMask.Select(value => value ? 1 : 0)), Is.EqualTo(data[10]));
                Assert.That(string.Join(";", port.Calls), Is.EqualTo(data[11]));
                return;
            }
            Assert.Fail("Unknown native vector kind " + data[0]);
        }

        [Test]
        public void ActiveDemandProtectsItsValueUntilTheActionDisappears()
        {
            var (ai, port, _) = Create("PAL3");
            SetRoles(ai, new[] { 0 }, new[] { 10 });
            ai.Demand[0, 1].ActionId = 7;
            port.Active = true;
            ai.UpdateDemands();
            Assert.That(ai.Demand[0, 1].Satisfy, Is.EqualTo(100));
            Assert.That(ai.Demand[0, 1].Handled, Is.True);
            port.Active = false;
            ai.UpdateDemands();
            Assert.That(ai.Demand[0, 1].Handled, Is.False);
            ai.UpdateDemands();
            Assert.That(ai.Demand[0, 1].Satisfy, Is.EqualTo(10));
        }

        [Test]
        public void MadnessAndChaosPreserveIndependentCapabilityRules()
        {
            var (ai, _, _) = Create("PAL3");
            ai.Roles[0].Chaos = true;
            Assert.That(ai.CapabilityEnabled(0, BattleAiAttemptKind.RecoverMagic), Is.True);
            ai.Roles[0].Madness = true;
            Assert.That(ai.CapabilityEnabled(0, BattleAiAttemptKind.RecoverMagic), Is.False);
            Assert.That(ai.CapabilityEnabled(0, BattleAiAttemptKind.Normal), Is.True);
        }

        private sealed class Port : BattleAiPort
        {
            public BattleAi Ai;
            public string Success;
            public int Scene, LastAbility;
            public bool RepeatCan, RepeatDead, RepeatAttack, Fallback, Active;
            public int RepeatTarget;
            public HashSet<int> Denied = new();
            public readonly List<string> Attempts = new();
            public readonly List<string> Eligibility = new();
            public readonly List<string> Calls = new();

            public override int SceneFiveSpiritMode => Scene;

            public override bool CanCast(int source, int skillId)
            {
                bool allowed = !Denied.Contains(skillId);
                Eligibility.Add(skillId + ":" + (allowed ? 1 : 0));
                return allowed;
            }

            public override long TryAttempt(BattleAiAttempt attempt)
            {
                if (Fallback)
                {
                    Calls.Add("FallbackPlayerNormal");
                    return 7;
                }
                bool accepted = attempt.Kind.ToString() == Success && !(attempt.Kind == BattleAiAttemptKind.Normal && attempt.Source == attempt.Target);
                LastAbility = attempt.AbilityId;
                string prefix = attempt.Kind + ":" + attempt.Source;
                Attempts.Add(attempt.Kind == BattleAiAttemptKind.SpecAI ? prefix + ":" + (accepted ? 1 : 0)
                    : prefix + ":" + attempt.Target + ":" + DemandOffset(attempt.Demand) + ":" + attempt.AbilityId + ":" + (accepted ? 1 : 0));
                return accepted ? 7 : -1;
            }

            private int DemandOffset(BattleAiDemand demand)
            {
                if (demand == null)
                    return -1;
                for (int role = 0; role < 11; role++)
                {
                    for (int kind = 0; kind < 10; kind++)
                    {
                        if (ReferenceEquals(Ai.Demand[role, kind], demand))
                            return 0x630 + role * 160 + kind * 16;
                    }
                }
                for (int kind = 0; kind < 10; kind++)
                {
                    if (ReferenceEquals(Ai.EnemyDemand[kind], demand))
                        return 0xd10 + kind * 16;
                    if (ReferenceEquals(Ai.FriendDemand[kind], demand))
                        return 0xdb0 + kind * 16;
                }
                throw new ArgumentException("Unknown demand.");
            }

            public override bool IsActionActive(long actionId) => Active;

            public override bool CanRepeat(int source, BattleAiCommand command)
            {
                Calls.Add("CanCast");
                return RepeatCan;
            }

            public override bool AllRepeatTargetsDead(BattleAiCommand command)
            {
                Calls.Add("AllTargetsDead");
                return RepeatDead;
            }

            public override bool IsRepeatAttack(BattleAiCommand command)
            {
                Calls.Add("IsAttack");
                return RepeatAttack;
            }

            public override int PickRepeatTarget(int source, bool enemy, bool filterBackRole)
            {
                Calls.Add("Pick:" + (enemy ? 2 : 1) + ":" + (filterBackRole ? source.ToString(CultureInfo.InvariantCulture) : ""));
                return RepeatTarget;
            }

            public override void ExpandRepeatRange(BattleAiCommand command) => Calls.Add("ExpandRange");

            public override long SubmitRepeat(BattleAiCommand command)
            {
                Calls.Add("Submit:" + command.Kind + ":" + unchecked((uint)command.Target));
                return 7;
            }
        }
    }
}
